# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs, offset=-1):
    return [v + offset for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: digest
def digest(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(gather(fold(shape(raw))))

